6908	// ================= FA4-FAITHFUL warp-specialized kernel (fwd_kernel_fa4) =====================
6909	// Reimplements the CUTLASS FA4 structure: ONE 256-row Q tile = 2 STACKED 128-row halves sharing K/V.
6910	// 16 warps: w0-3 Softmax0(rows0-127), w4-7 Softmax1(rows128-255), w8-11 Correction, w12 MMA,
6911	// w13 Load(TMA K/V), w14 Epilogue, w15 Empty. tmem: S0@0 S1@128 P0@0 P1@128(alias S) O0@256 O1@384.
6912	// Pipelines (all depth-1 except KV ring; Q preloaded so no Q pipe; order_s01 omitted, perf-only):
6913	//   KV (Load->MMA), S0/S1 (MMA->Softmax, P-ready via p_full), C0/C1 (Softmax->Corr, stats via smem),
6914	//   O0/O1 (MMA->Corr), E (Corr->Epilogue, sO smem).  Stats (corr factor + final sum/max) travel via
6915	//   smem (sScale/sFin*) gated by the C barriers (like ws2), not tmem V0/V1.  Q is PRESCALED by
6916	//   scale*log2e at load, so softmax is p=ex2(S-m) and the corr factor is ex2(m_old-m_new).
6917	// Milestone target: CORRECT on non-causal (also handles causal / gqa). KVS=1 (serial K/V; correctness
6918	// first). O-side split: MMA acquires o_empty (correction rescaled O) before each PV.
6919	// Max K/V ring depth any instantiation uses. fwd_kernel_fa4_paged runs a DECOUPLED ring (K deeper than
6920	// V) because PC sampling showed its producer starved for ring slots, not for issue slots.
6921	constexpr int FA4KVSMAX = 3;
6922	struct BarsFA4 { uint64_t kf_full[FA4KVS], vf_full[FA4KVS], kv_empty[FA4KVS], s_full[2], p_full[2], o_full[2], o_empty[2], c_full[4], c_empty[4], q_full[1], q_empty[1], q_tma[1], q_sched[1], ord[2]; }; // D4: c_full/c_empty are [half*2+slot] depth-2
6923	// WINDOW/SINK/PADQ: template-gated feature grafts (ported line-for-line from fwd_kernel_ws2). The default
6924	// instantiation <T,HD,HDV,false,false,false> compiles to byte-identical SASS (all new code behind if constexpr).
6925	//   WINDOW: sliding-window (win_l/win_r) tile-range prune (n_lo..n_hi) + per-element band mask in boundary tiles.
6926	//   SINK:   attention sink (s_aux) folded into final (m,l) + O-scale (osc) at the softmax/correction handoff.
6927	//   PADQ:   hd<HD (e.g. hd96->HD=128) support: zero sQ pad cols [rhd,HD) after TMA-Q (Q=0 nullifies QK garbage).
6928	//   PAGED:  paged K/V cache. `mapK`/`mapV` become PAGE descriptors (box [64, segrows] over the pool
6929	//           viewed 2D as [num_rows, hkv*hd]), so a WTN-key tile is WTN/segrows contiguous physical page
6930	//           segments = nseg*(HD/64+HDV/64) TMA boxes instead of one. seqlen_k comes from seqused_k[b] and
6931	//           the base row from the page table. Everything else -- persistent LPT scheduling, the dual
6932	//           stacked-half softmax ping-pong, the correction/epilogue warpgroups, the cross-tile K/V ring --
6933	//           is shared with the dense path, which is the point: the separate non-persistent
6934	//           fwd_kernel_fa4_paged tops out near 0.70x where this kernel reaches 0.91-1.19x on dense.
6935	template<class T, int HD, int HDV, bool WINDOW=false, bool SINK=false, bool PADQ=false, bool PAGED=false>
6936	__global__ void __launch_bounds__(512,1) fwd_kernel_fa4(
6937	    const __grid_constant__ CUtensorMap mapK, const __grid_constant__ CUtensorMap mapV,
6938	    const __grid_constant__ CUtensorMap mapQ,
6939	    const T* __restrict__ q, T* __restrict__ out, float* __restrict__ lse,
6940	    const int* __restrict__ cu_q, const int* __restrict__ cu_k,
6941	    int hq, int hkv, int rep, float scale, int is_causal, int win_l, int win_r,
6942	    float softcap, const float* __restrict__ s_aux, int rhd, int rhdv,
6943	    int* __restrict__ tile_ctr, int total_tiles, int gx, int nB, int ragged,
6944	    const int* __restrict__ page_table, int pt_stride, int block_size,
6945	    const int* __restrict__ seqused_k, int pt_seg, int grp,
6946	    const T* __restrict__ kptr, const T* __restrict__ vptr) {   // raw pool pointers: PAGED software gather only
6947	    // PERSISTENT + CONTINUOUS-OVERLAP fa4 (persist-lpt). Grid = NSM CTAs; each CTA grabs 256-row tiles via
6948	    // atomicAdd(tile_ctr) in LPT (heaviest-mb-first) order. NO per-tile __syncthreads drain: tile N's
6949	    // correction/epilogue (O-drain + direct global write) overlaps tile N+1's mainloop. Roles: w0-3 Softmax0,
6950	    // w4-7 Softmax1, w8-11 Correction (O-rescale + final normalize + DIRECT global write + lse; sO removed),
