7190	                const uint32_t kfb=KF[s], vfb=VF[s];
7191	                if(lid==0){ mbar_expect(kfb, WTN*HD*2); mbar_expect(vfb, WTN*HDV*2); }
7192	                asm volatile("bar.sync 8, %0;"::"r"(LDN));   // expect_tx ordered ahead of every gather/box
7193	                if(segrows>0){
7194	                  if(lid<nseg){ int kk=key0+lid*segrows;
7195	                    // Tail segments past seqlen_k have no valid page-table entry: pull pool row 0 and let
7196	                    // the boundary softmax mask those keys (p=0), so V garbage cannot reach O.
7197	                    int y = (kk<seqlen_k) ? (page_table[b*pt_stride+kk/block_size]*block_size + kk%block_size) : 0;
7198	                    int dof = lid*segrows*64;
7199	                    for(int cb=0;cb<KCB;cb++) tma_box(sK[s]+cb*8192+dof, &mapK, hk*rhd +cb*64, y, kfb);
7200	                    for(int cb=0;cb<VCB;cb++) tma_box(sV[s]+cb*8192+dof, &mapV, hk*rhdv+cb*64, y, vfb); }
7201	                } else {
7202	                  // page_size < 8: no multi-row box is expressible, so gather 4 rows per issue with
7203	                  // tile::gather4 -- NGT = (WTN/4)*(KCB+VCB) = 128 issues at hd128, two per lane across the
7204	                  // two load warps. Each lane resolves the 4 page rows its issue needs directly (512 L1/L2-hot
7205	                  // page_table reads per tile against 128 distinct ones -- redundant but independent, which is
7206	                  // what matters: this producer is latency-bound, not issue-bound).
7207	                  // The software cp.async gather FA4 uses here was tried and lost badly (0.30-0.33x): 4096
7208	                  // 16B copies from 64 threads is 64 issues per lane per block, and this kernel's producer
7209	                  // tier cannot hold the address state. Kept behind FA4_PFSW for the record.
7210	                  constexpr int NG=WTN/4, NGK=NG*KCB, NGT=NGK+NG*VCB;
7211	                  #pragma unroll 1
7212	                  for(int op=lid; op<NGT; op+=LDN){
7213	                      bool isK=op<NGK; int o=isK?op:op-NGK; int cb=o/NG, g=o-cb*NG;
7214	                      int kk=key0+4*g, y0,y1,y2,y3;
7215	                      y0=(kk+0<seqlen_k)?(page_table[b*pt_stride+(kk+0)/block_size]*block_size+(kk+0)%block_size):0;
7216	                      y1=(kk+1<seqlen_k)?(page_table[b*pt_stride+(kk+1)/block_size]*block_size+(kk+1)%block_size):0;
7217	                      y2=(kk+2<seqlen_k)?(page_table[b*pt_stride+(kk+2)/block_size]*block_size+(kk+2)%block_size):0;
7218	                      y3=(kk+3<seqlen_k)?(page_table[b*pt_stride+(kk+3)/block_size]*block_size+(kk+3)%block_size):0;
7219	                      if(isK) tma_gather4(sK[s]+cb*8192+4*g*64, &mapK, hk*rhd +cb*64, y0,y1,y2,y3, kfb);
7220	                      else    tma_gather4(sV[s]+cb*8192+4*g*64, &mapV, hk*rhdv+cb*64, y0,y1,y2,y3, vfb);
7221	                  }
7222	                }
7223	              } else {
7224	                if(lead){ int y=k0+i*WTN; if constexpr(WINDOW) y=k0+(n_lo+i)*WTN;
7225	                    // K first (needed by QK), signal on its own barrier so QK runs ahead of the V load.
7226	                    mbar_expect(KF[s], WTN*HD*2);
7227	                    for(int cb=0;cb<KCB;cb++) tma_box(sK[s]+cb*8192, &mapK, hk*rhd+cb*64, y, KF[s]);
7228	                    mbar_expect(VF[s], WTN*HDV*2);
7229	                    for(int cb=0;cb<VCB;cb++) tma_box(sV[s]+cb*8192, &mapV, hk*rhdv+cb*64, y, VF[s]); } }
7230	              }
7231	        }
7232	    } else if (warp==12) {               // -------- MMA warp --------
7233	        uint32_t KF[FA4KVS],VF[FA4KVS],KVE[FA4KVS]; for(int s=0;s<FA4KVS;s++){ KF[s]=smem_u32(&bars.kf_full[s]); VF[s]=smem_u32(&bars.vf_full[s]); KVE[s]=smem_u32(&bars.kv_empty[s]); }
7234	        const uint32_t SF[2]={smem_u32(&bars.s_full[0]),smem_u32(&bars.s_full[1])};
7235	        const uint32_t PF[2]={smem_u32(&bars.p_full[0]),smem_u32(&bars.p_full[1])};
7236	        const uint32_t OF[2]={smem_u32(&bars.o_full[0]),smem_u32(&bars.o_full[1])};
7237	        const uint32_t OE[2]={smem_u32(&bars.o_empty[0]),smem_u32(&bars.o_empty[1])};

