140	// ---- register-resident ring/slot accessors -------------------------------------------------------
141	// `a[s]` with a RUNTIME s forces the array into LOCAL memory (SASS: a prologue `STL.128 [R1]` plus an
142	// `LDL [R+s*4]` per use). Every pipelined kernel here indexes its ring state -- K/V mbarriers, smem
143	// bases, MMA descriptors, phase bits, the correction WG's depth-2 C-channel tables -- by `s = i % KVS`
144	// or the depth-2 slot, all inside the per-K-block loop. NCU on attn_real_llama8b_pf_s16k
145	// (fwd_kernel_fa4_paged, page_size 1): 38.6M local-memory LOAD sectors against just 6.5M global ones,
146	// long_scoreboard 9.21/issue vs FA4's 1.95, tensor pipe 31.7% vs FA4's 71.6%, DRAM under 2% on both --
147	// the kernel is spill-bound, not bandwidth-bound. An unrolled compare-select chain keeps the tables in
148	// registers; at these depths (2) it is a single ISETP+SEL.
149	template<int N, class V> __device__ __forceinline__ V rsel(const V (&a)[N], int s){
150	    V r=a[0];
151	    #pragma unroll
152	    for(int t=1;t<N;++t) if(s==t) r=a[t];
153	    return r;
154	}
155	// Read-and-flip an mbarrier phase bit (`p=a[s]; a[s]^=1;`) without a local array.
156	template<int N> __device__ __forceinline__ int rflip(int (&a)[N], int s){
157	    int r=a[0];
158	    #pragma unroll
159	    for(int t=1;t<N;++t) if(s==t) r=a[t];
160	    #pragma unroll
161	    for(int t=0;t<N;++t) if(s==t) a[t]=r^1;
162	    return r;
163	}
164	// Depth-batched O-rescale: issue DEPTH tmem loads, ONE wait, packed-f32x2 mul, DEPTH stores. DEPTH=1 == rolled
165	// (32 live regs, spill-free at 64); DEPTH=2 (64 regs) overlaps 2 read latencies; DEPTH=4 == full batch (128 regs).
166	template<int HDV, int DEPTH>
167	__device__ __forceinline__ void tmem_o_rescale_d(uint32_t a0, float corr){
168	    const unsigned long long c2=bcast2(corr);
169	    #pragma unroll 1
170	    for(int bg=0; bg<HDV; bg += DEPTH*32){
171	        uint32_t og[DEPTH*32];
172	        #pragma unroll
173	        for(int d=0; d<DEPTH; ++d) tmem_ld32(a0+(uint32_t)(bg+d*32), og+d*32);
174	        tmem_wait_ld();
175	        #pragma unroll
176	        for(int t=0;t<DEPTH*32;t+=2) pmul2(og[t],og[t+1],c2);
177	        #pragma unroll
178	        for(int d=0; d<DEPTH; ++d) tmem_st32(a0+(uint32_t)(bg+d*32), og+d*32);
179	    }
180	}
181	__device__ __forceinline__ float ex2f(float x){ float r; asm volatile("ex2.approx.ftz.f32 %0,%1;":"=f"(r):"f"(x)); return r; }
182	
183	// 128B swizzle, ROWS=128 tile: koff = K-major (Q,K), voff = MN-major (V). Byte-identical for any
184	// 16-bit element (bf16/fp16). Reused from the validated FA3 layout.
185	__device__ __forceinline__ int koff(int r,int c){ return (c>>6)*8192 + r*64 + ((c&63)^((r&7)<<3)); }
186	__device__ __forceinline__ int voff(int key,int dv){ return (dv>>6)*8192 + key*64 + ((dv&63)^((key&7)<<3)); }
187	__device__ __forceinline__ uint64_t make_desc(uint32_t addr,uint32_t lbo,uint32_t sbo,int lt){
188	    uint64_t d=0; d|=(uint64_t)((addr>>4)&0x3FC0u); d|=(uint64_t)((lbo>>4)&0x3FFFu)<<16;
189	    d|=(uint64_t)((sbo>>4)&0x3FFFu)<<32; d|=(uint64_t)1u<<46; d|=(uint64_t)(lt&0x7u)<<61; return d; }
190	__device__ __forceinline__ uint64_t desc_add(uint64_t b,uint32_t off){
191	    uint32_t lo,hi; asm("mov.b64 {%0,%1}, %2;":"=r"(lo),"=r"(hi):"l"(b));
192	    lo+=off; uint64_t r; asm("mov.b64 %0,{%1,%2};":"=l"(r):"r"(lo),"r"(hi)); return r; }
193	__device__ __forceinline__ uint32_t qk_doff(int kb){ return (uint32_t)((kb&3)*2 + (kb>>2)*1024); }
194	__device__ __forceinline__ uint32_t v_doff(int kb){ return (uint32_t)(kb*0x80); }
195	
196	// Pack two fp32 -> one 32b of two 16-bit elems (low=a, high=b) via a SINGLE packed convert instruction
